svg.script:
for (let text of document.getElementsByTagName('text')) {
  let [first, second] = text.getAttribute('expected-x').split(' ').map(parseFloat);
  let dx = text.querySelector('tspan').getAttribute('dx');
  let description = 'text-anchor=' + text.getAttribute('text-anchor') + ', ' + text.textContent.trim() + (dx ? ', dx=' + dx : '');
  promise_test(async t => {
    await document.fonts.load('20px Ahem');
    await document.fonts.ready;
    assert_approx_equals(text.getStartPositionOfChar(0).x, first, 0.5, 'first chunk');
    assert_approx_equals(text.getStartPositionOfChar(2).x, second, 0.5, 'second chunk');
  }, description);
}
